use verus::prelude::*;

verus! {

    /// Given two vectors `a` and `b` of equal length, returns a new vector
    /// whose i-th element is `a[i] & b[i]`.
    fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
        requires
            a.len() == b.len(),
        ensures
            result.len() == a.len(),
        ensures
            forall |i: usize| i < a.len() ==> result[i] == a[i] & b[i],
    {
        // We'll build up the result vector element by element.
        let mut res: Vec<u8> = Vec::new();
        // preallocate space to avoid re-allocations
        res.reserve(a.len());

        let mut i: usize = 0;
        while i < a.len() {
            // Loop invariants to help the verifier
            invariant(i <= a.len());
            invariant(res.len() == i);
            invariant(forall |j: usize| j < i ==> res[j] == a[j] & b[j]);
            decreases(a.len() - i);

            // Compute the bitwise AND at index i and append
            res.push(a[i] & b[i]);
            i += 1;
        }

        res
    }

    #[proof]
    fn test_bitwise_and() {
        let a = vec![1u8, 3, 7, 255];
        let b = vec![2u8, 1, 5, 15];
        let r = bitwise_and(a.clone(), b.clone());
        // check manually that each entry is correct
        assert(r.len() == 4);
        assert(r[0] == 1 & 2);
        assert(r[1] == 3 & 1);
        assert(r[2] == 7 & 5);
        assert(r[3] == 255 & 15);
    }
}